SELECT id, template_code, template_name, contract_type, version, payment_terms, default_payment_days, default_penalty_rate, sla_description, deliverables, content, customer_level, project_level, status, author_id, author_name, remark, tenant_id, created_by, created_at, updated_by, updated_at, deleted
FROM ydsz_project_contract_template

    deleted = 0

        AND contract_type = #{contractType}


        AND status = #{status}


ORDER BY created_at DESC

SELECT COUNT(1) FROM ydsz_project_contract_template
WHERE contract_type = #{contractType}

      AND status = #{status}

  AND deleted = 0
